CREATE TABLE IF NOT EXISTS public.config (key text PRIMARY KEY,value jsonb NOT NULL,updated_at timestamptz DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS public.gallery (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,url text,caption text,type text DEFAULT 'image',created_at timestamptz DEFAULT CURRENT_TIMESTAMP,name text);
CREATE TABLE IF NOT EXISTS public.lots (id text PRIMARY KEY,size text,price numeric,status text DEFAULT 'Dispon�vel',"desc" text,client text,client_cpf text,payments jsonb DEFAULT '[]',administrative_docs jsonb DEFAULT '{}',created_at timestamptz DEFAULT CURRENT_TIMESTAMP,updated_at timestamptz DEFAULT CURRENT_TIMESTAMP,"paymentStatus" text DEFAULT '-',"parcelasPagas" integer DEFAULT 0,"totalParcelas" integer DEFAULT 120);
CREATE TABLE IF NOT EXISTS public.map_mapped (id text PRIMARY KEY,top numeric NOT NULL,"left" numeric NOT NULL,width numeric NOT NULL,height numeric NOT NULL,created_at timestamptz DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS public.users (id uuid DEFAULT gen_random_uuid() PRIMARY KEY,cpf text NOT NULL UNIQUE,name text NOT NULL,email text,telefone text,password text NOT NULL,status text DEFAULT 'pending',lote_id text,simulation jsonb,total_parcelas integer,start_date timestamptz,created_at timestamptz DEFAULT CURRENT_TIMESTAMP,approved_at timestamptz,profile jsonb);
CREATE TABLE IF NOT EXISTS public.app_admins (id uuid DEFAULT gen_random_uuid() PRIMARY KEY,login text UNIQUE NOT NULL,password_hash text NOT NULL,created_at timestamptz DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS public.app_sessions (token_hash text PRIMARY KEY,user_id uuid NOT NULL,role text NOT NULL CHECK(role IN ('admin','client')),expires_at timestamptz NOT NULL,created_at timestamptz DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS app_sessions_expires_idx ON public.app_sessions(expires_at);
CREATE TABLE IF NOT EXISTS public.app_rate_limits (key text PRIMARY KEY,count integer NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS public.app_files (id uuid PRIMARY KEY,bucket text NOT NULL,object_key text NOT NULL UNIQUE,content_type text NOT NULL,size_bytes bigint NOT NULL,visibility text NOT NULL CHECK(visibility IN ('public','private')),owner_id uuid,lot_id text,purpose text NOT NULL,ready boolean NOT NULL DEFAULT false,created_at timestamptz DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS public.app_migrations (id text PRIMARY KEY,checksum text NOT NULL,applied_at timestamptz DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS users_cpf_normalized_idx ON public.users ((regexp_replace(cpf,'[^0-9]','','g')));
